 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { assignIssueSchema, type AssignIssueInput } from "@/schemas/issue";
import { assignIssue } from "@/server/services/issue-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";

const run = withAction<typeof assignIssueSchema, Issue>(
  assignIssueSchema,
  async (raw, actor) => {
    const input = raw as AssignIssueInput;

    const allowed = can(actor, "issue:assign", {
      kind: "issue",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: input.issueId,
      authorId: actor.userId,
      assigneeId: input.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:assign");
    }

    const issue = await assignIssue(actor, input);
    revalidateTagged([issueTag(issue.id)], CACHE_PROFILES.seconds);
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "seconds" },
);

export async function assignIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}

"use server";

/**
 * Edits a comment the actor authored.
 *
 * Owner D. The `can()` call here is an optimistic pre-check made with the
 * caller as the presumed author, so a viewer is rejected before the round trip;
 * `CommentService.updateComment` repeats the check with the persisted
 * `authorId`, which is what actually enforces "only your own comments".
 *
 * Must call (do not reimplement): updateCommentSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateCommentSchema, type UpdateCommentInput } from "@/schemas/comment";
import { updateComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const run = withAction<typeof updateCommentSchema, Comment>(
  updateCommentSchema,
  async (raw, actor) => {
    const input = raw as UpdateCommentInput;

    const allowed = can(actor, "comment:update", {
      kind: "comment",
      orgId: input.orgId,
      commentId: input.commentId,
      authorId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("comment:update");
    }

    const comment = await updateComment(actor, input);
    revalidateTagged(["comments"], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function updateCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}

"use server";

/**
 * Board drag-and-drop target; reconciles the optimistic update.
 *
 * Owner D. The client has already moved the card via `useOptimisticIssues`, so
 * the only thing that matters here is returning the authoritative row — the
 * hook reconciles against it and snaps the card back if the move was refused.
 * Dragging is only reachable when `kanban_board` is on, and the flag is
 * re-checked server-side because the client copy is only a snapshot.
 *
 * Must call (do not reimplement): moveIssueSchema, can, isEnabled, getActor,
 * toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
} from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { moveIssueSchema, type MoveIssueInput } from "@/schemas/issue";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { moveIssue } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";

const run = withAction<typeof moveIssueSchema, Issue>(
  moveIssueSchema,
  async (raw, actor) => {
    const input = raw as MoveIssueInput;

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: input.issueId,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:update");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("kanban_board", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("kanban_board");
    }

    const issue = await moveIssue(actor, input);
    revalidateTagged(
      [issueTag(issue.id), projectTag(issue.projectId)],
      CACHE_PROFILES.seconds,
    );
    return issue;
  },
  { revalidate: ["board"], cacheProfile: "seconds" },
);

export async function moveIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}

