function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const known = new Set(members.items.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}
/**
 * Attachment metadata plus the storage quota guard.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { assertCanViewProject } from "@/server/services/project-service";
import { issueResource, requireFound } from "./_support";
import type {
  CreateAttachmentInput,
  DeleteAttachmentInput,
} from "@/schemas/attachment";
import type { IssueId, OrgId } from "@/types/common";
import type { IssueAttachment } from "@/types/issue";
import type { Actor } from "@/types/member";

const BYTES_PER_MB = 1024 * 1024;

export async function listAttachments(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueAttachment[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  await assertIssueProjectVisible(actor, issue);
  assertCan(actor, "issue:read", issueResource(issue));

  return attachmentRepo.listAttachments(orgId, issueId);
}

/**
 * Records an upload after checking the org still has storage left. The quota
 * is in megabytes and the upload is in bytes, so the incoming size is rounded
 * up to whole megabytes before the comparison — half a megabyte still costs
 * one against the plan.
 */
export async function addAttachment(
  actor: Actor,
  input: CreateAttachmentInput,
): Promise<IssueAttachment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  await assertIssueProjectVisible(actor, issue);
  assertCan(actor, "issue:update", issueResource(issue));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usage = await usageRepo.getUsage(input.orgId);
  const requestedMb = Math.ceil(input.sizeBytes / BYTES_PER_MB);

  if (
    wouldExceedLimit(org.plan, "storageMb", usage.storageMbUsed, requestedMb)
  ) {
    throw new Error(
      `Plan ${org.plan} has no room for another ${requestedMb} MB`,
    );
  }

  const attachment = await attachmentRepo.insertAttachment(
    input,
    actor.userId,
  );
  await usageRepo.incrementUsage(input.orgId, { storageMbUsed: requestedMb });

  return attachment;
}

/** Removing an attachment gives the megabytes back to the quota. */
export async function removeAttachment(
  actor: Actor,
  input: DeleteAttachmentInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);

  const attachment = requireFound(
    await findAttachment(input.orgId, input.attachmentId),
    "Attachment",
    input.attachmentId,
  );

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, attachment.issueId),
    "Issue",
    attachment.issueId,
  );
  await assertIssueProjectVisible(actor, issue);
  assertCan(actor, "issue:update", issueResource(issue));

  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
  await usageRepo.incrementUsage(input.orgId, {
    storageMbUsed: -Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
  });
}

async function assertIssueProjectVisible(
  actor: Actor,
  issue: { readonly orgId: OrgId; readonly projectId: import("@/types/common").ProjectId },
): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(issue.orgId, issue.projectId),
    "Project",
    issue.projectId,
  );
  await assertCanViewProject(actor, project);
}

/**
 * The attachment repository only reads by issue, because that is the only way
 * the UI ever reaches one. A delete arrives with just an id, so the org's
 * issues are walked until the row turns up.
 */
async function findAttachment(
  orgId: OrgId,
  attachmentId: string,
): Promise<IssueAttachment | null> {
  const page = await issueRepo.listIssues({
    orgId,
    limit: 100,
    cursor: null,
    includeArchived: true,
  });

  for (const issue of page.items) {
    const rows = await attachmentRepo.listAttachments(orgId, issue.id);
    const match = rows.find((row) => row.id === attachmentId);
    if (match) return match;
  }

  return null;
}

/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof NotFoundError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof NotFoundError) {
    return {
      code: "not_found",
      message: "That resource was not found.",
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}

"use server";

/**
 * Updates project metadata.
 *
 * Owner D. Visibility is part of this payload, which is why the permission
 * resource carries the *incoming* visibility: raising a project to `public`
 * must be judged against what it is becoming, not what it was.
 *
 * Must call (do not reimplement): updateProjectSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateProjectSchema, type UpdateProjectInput } from "@/schemas/project";
import { updateProject } from "@/server/services/project-service";
import { requireVisibleProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof updateProjectSchema, Project>(
  updateProjectSchema,
  async (raw, actor) => {
    const input = raw as UpdateProjectInput;

    await requireVisibleProject(actor, input.orgId, input.projectId);

    const allowed = can(actor, "project:update", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: input.visibility ?? "org",
      leadId: input.leadId ?? actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:update");
    }

    const project = await updateProject(actor, input);
    revalidateTagged([projectTag(project.id)], CACHE_PROFILES.minutes);
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function updateProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}

/**
 * Issue rows: the widest query surface in the app. Every method takes `orgId` first and honours `IssueFilter.includeArchived`.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived
 */
import {
  and,
  count,
  desc,
  eq,
  inArray,
  isNotNull,
  isNull,
  like,
  lt,
  ne,
  or,
  sql,
} from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import {
  attachments,
  comments,
  getDb,
  issueLabels,
  issues,
  projectMembers,
  projects,
} from "@/server/db";
import { ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toIssue } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type {
  CreateIssueInput,
  IssueFilterInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type {
  ArchiveScope,
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  Page,
  ProjectId,
  UserId,
} from "@/types/common";
import type {
  Issue,
  IssueBoardColumn,
  IssueStatus,
  IssueWithRelations,
} from "@/types/issue";
import type { SQL } from "drizzle-orm";

/** Statuses whose entry stamps `completed_at`; leaving one clears it again. */
const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export async function findIssueById(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();
  if (!row) return null;

  const labels = await listLabelsForIssues(orgId, [row.id as IssueId]);
  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
}

export async function findIssueByNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue | null> {
  const row = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        eq(issues.number, issueNumber),
      ),
    )
    .get();
  return row ? toIssue(row) : null;
}

type IssueListAccess = {
  readonly userId: UserId;
  readonly includePrivate: boolean;
};

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(
  input: IssueFilterInput,
  access?: IssueListAccess,
): readonly SQL[] {
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };
  const db = getDb();

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    access === undefined || access.includePrivate
      ? undefined
      : inArray(
          issues.projectId,
          db
            .select({ projectId: projects.id })
            .from(projects)
            .where(
              and(
                orgPredicate(projects.orgId, input.orgId),
                or(
                  ne(projects.visibility, "private"),
                  eq(projects.leadId, access.userId),
                  inArray(
                    projects.id,
                    db
                      .select({ projectId: projectMembers.projectId })
                      .from(projectMembers)
                      .where(
                        and(
                          orgPredicate(projectMembers.orgId, input.orgId),
                          eq(projectMembers.userId, access.userId),
                        ),
                      ),
                  ),
                ),
              ),
            ),
        ),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...input.status]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined || input.labelIds.length === 0
      ? undefined
      : inArray(
          issues.id,
          getDb()
            .select({ id: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, input.orgId),
                inArray(issueLabels.labelId, [...input.labelIds]),
              ),
            ),
        ),
  );
}

export async function listIssues(
  input: IssueFilterInput,
  access?: IssueListAccess,
): Promise<Page<Issue>> {
  const db = getDb();
  const filters = issueFilters(input, access);
  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };

  const total = db
    .select({ value: count() })
    .from(issues)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(issues)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(issues.createdAt), desc(issues.id))
    .limit(probeLimit(input.limit))
    .all();

  const labels = await listLabelsForIssues(
    input.orgId,
    rows.map((row) => row.id as IssueId),
  );

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
    (row) => ({ id: row.id, sortValue: row.createdAt }),
  );
}

/**
 * The list view needs comment and attachment counts per row. Two grouped
 * queries beat N+1 round trips, so the counts are folded in afterwards.
 */
export async function listIssuesWithRelations(
  input: IssueFilterInput,
  access?: IssueListAccess,
): Promise<Page<IssueWithRelations>> {
  const db = getDb();
  const page = await listIssues(input, access);
  const ids = page.items.map((issue) => issue.id);
  if (ids.length === 0) {
    return { items: [], nextCursor: page.nextCursor, total: page.total };
  }

  const commentCounts = db
    .select({ issueId: comments.issueId, value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        inArray(comments.issueId, [...ids]),
        isNull(comments.archivedAt),
      ),
    )
    .groupBy(comments.issueId)
    .all();

  const attachmentCounts = db
    .select({ issueId: attachments.issueId, value: count() })
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, input.orgId),
        inArray(attachments.issueId, [...ids]),
      ),
    )
    .groupBy(attachments.issueId)
    .all();

  const labels = await listLabelsForIssues(input.orgId, ids);
  const commentsBy = new Map(commentCounts.map((r) => [r.issueId, r.value]));
  const attachmentsBy = new Map(
    attachmentCounts.map((r) => [r.issueId, r.value]),
  );

  return {
    items: page.items.map((issue) => ({
      issue,
      labels: labels[issue.id] ?? [],
      commentCount: commentsBy.get(issue.id) ?? 0,
      attachmentCount: attachmentsBy.get(issue.id) ?? 0,
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/** One column per status, in `ISSUE_STATUSES` order, live rows only. */
export async function listBoardColumns(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(desc(issues.updatedAt))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return ISSUE_STATUSES.map((status) => {
    const column = rows
      .filter((row) => row.status === status)
      .map((row) => toIssue(row, (labels[row.id] ?? []).map((l) => l.id)));
    return { status, issues: column, total: column.length };
  });
}

export async function countIssues(
  orgId: OrgId,
  projectId: ProjectId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,
      startedAt: null,
      completedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  if (input.labelIds.length > 0) {
    db.insert(issueLabels)
      .values(
        input.labelIds.map((labelId) => ({
          orgId: input.orgId,
          issueId: row.id,
          labelId,
        })),
      )
      .run();
  }

  return toIssue(row, input.labelIds);
}

export async function updateIssue(input: UpdateIssueInput): Promise<Issue> {
  const db = getDb();
  const row = db
    .update(issues)
    .set({
      ...(input.title === undefined ? {} : { title: input.title }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.priority === undefined ? {} : { priority: input.priority }),
      ...(input.estimate === undefined ? {} : { estimate: input.estimate }),
      ...(input.dueAt === undefined ? {} : { dueAt: input.dueAt }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(issues.orgId, input.orgId),
        eq(issues.id, input.issueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${input.issueId} not found`);

  if (input.labelIds !== undefined) {
    db.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, input.orgId),
          eq(issueLabels.issueId, input.issueId),
        ),
      )
      .run();
    if (input.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          input.labelIds.map((labelId: LabelId) => ({
            orgId: input.orgId,
            issueId: input.issueId,
            labelId,
          })),
        )
        .run();
    }
  }

  const labels = await listLabelsForIssues(input.orgId, [input.issueId]);
  return toIssue(row, (labels[input.issueId] ?? []).map((label) => label.id));
}

/** Status transitions maintain `started_at` / `completed_at` bookkeeping. */
export async function setIssueStatus(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const current = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const row = getDb()
    .update(issues)
    .set({
      status,
      startedAt:
        status === "in_progress" && current.startedAt === null
          ? stamp
          : current.startedAt,
      completedAt: TERMINAL_STATUSES.includes(status) ? stamp : null,
      updatedAt: stamp,
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  return toIssue(row);
}

