import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}

/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";
import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import {
  idColumn,
  softDeleteColumns,
  tenantColumns,
  timestampColumns,
} from "./_shared";

export const projects = sqliteTable(
  "projects",
  {
    id: idColumn(),
    ...tenantColumns,
    name: text("name").notNull(),
    slug: text("slug").notNull(),
    key: text("key").notNull(),
    description: text("description"),
    visibility: text("visibility", { enum: ["private", "org", "public"] })
      .notNull()
      .default("org"),
    status: text("status", { enum: ["active", "paused", "completed"] })
      .notNull()
      .default("active"),
    leadId: text("lead_id"),
    color: text("color").notNull().default("#6366f1"),
    startsAt: text("starts_at"),
    targetDate: text("target_date"),
    ...timestampColumns,
    ...softDeleteColumns,
  },
  (table) => [
    uniqueIndex("projects_org_slug_idx").on(table.orgId, table.slug),
    uniqueIndex("projects_org_key_idx").on(table.orgId, table.key),
    index("projects_org_archived_idx").on(table.orgId, table.archivedAt),
  ],
);

export const projectMembers = sqliteTable(
  "project_members",
  {
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    userId: text("user_id").notNull(),
    addedAt: text("added_at").notNull(),
  },
  (table) => [
    uniqueIndex("project_members_pk").on(table.projectId, table.userId),
    index("project_members_org_idx").on(table.orgId),
  ],
);

export type ProjectRow = typeof projects.$inferSelect;
export type NewProjectRow = typeof projects.$inferInsert;
export type ProjectMemberRow = typeof projectMembers.$inferSelect;
"use server";

/**
 * Edits a comment the actor authored.
 *
 * Owner D. The `can()` call here is an optimistic pre-check made with the
 * caller as the presumed author, so a viewer is rejected before the round trip;
 * `CommentService.updateComment` repeats the check with the persisted
 * `authorId`, which is what actually enforces "only your own comments".
 *
 * Must call (do not reimplement): updateCommentSchema, can, getActor,
 * toActionResult
 */

import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { updateCommentSchema, type UpdateCommentInput } from "@/schemas/comment";
import { updateComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const run = withAction<typeof updateCommentSchema, Comment>(
  updateCommentSchema,
  async (raw, actor) => {
    const input = raw as UpdateCommentInput;

    const comment = await updateComment(actor, input);
    revalidateTagged(["comments"], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function updateCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}
"use server";

/**
 * Soft-deletes a comment.
 *
 * Owner D. Deletion is a soft delete: `CommentService` stamps `archived_at`
 * through `archivePatch()` and the thread query filters it out, so replies
 * hanging off the comment keep their parent id.
 *
 * Must call (do not reimplement): deleteCommentSchema, can, getActor,
 * toActionResult
 */

import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { deleteCommentSchema, type DeleteCommentInput } from "@/schemas/comment";
import { deleteComment } from "@/server/services/comment-service";
import type { ActionResult } from "@/types/api";
import type { Comment } from "@/types/comment";

const run = withAction<typeof deleteCommentSchema, Comment>(
  deleteCommentSchema,
  async (raw, actor) => {
    const input = raw as DeleteCommentInput;

    const comment = await deleteComment(actor, input);
    revalidateTagged([issueTag(comment.issueId)], CACHE_PROFILES.seconds);
    return comment;
  },
  { revalidate: ["comments"], cacheProfile: "seconds" },
);

export async function deleteCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
  return run(raw);
}

